{
  "name": "open-shopify",
  "version": "1.0.0",
  "private": true,
  "description": "Open Shopify — Open-Source Enterprise Commerce Engine (Shopify-Killer Architecture) with OmniShop Multi-Platform POS",
  "workspaces": [
    "apps/*",
    "packages/*"
  ],
  "scripts": {
    "build": "turbo run build",
    "dev": "turbo run dev",
    "lint": "turbo run lint",
    "test": "turbo run test",
    "clean": "turbo run clean && rm -rf node_modules",
    "db:generate": "pnpm --filter @vendr/database generate",
    "db:push": "pnpm --filter @vendr/database push",
    "db:seed": "pnpm --filter @vendr/database seed"
  },
  "devDependencies": {
    "turbo": "^2.4.4",
    "typescript": "^5.7.3",
    "prettier": "^3.5.0"
  },
  "packageManager": "pnpm@12.21.0",
  "pnpm": {
    "onlyBuiltDependencies": [
      "@prisma/client",
      "@prisma/engines",
      "prisma",
      "esbuild",
      "@turbo/windows-64"
    ]
  },
  "engines": {
    "node": ">=20.0.0"
  }
}

{
  "project": "Open Shopify",
  "name": "open-shopify",
  "version": "1.0.0",
  "description": "Open Shopify — Open-Source Enterprise Commerce Engine (Shopify-Killer Architecture) with OmniShop Multi-Platform POS",
  "constitution": {
    "playwright_ban": true,
    "no_ai_slop": true,
    "karpathy_verification_gates": true,
    "token_context_discipline": true
  },
  "current_phase": 10,
  "phases": [
    {
      "phase": 1,
      "title": "Deep Reverse-Engineering & Architectural Blueprint",
      "status": "done",
      "stories": [
        {
          "id": "PHASE1-01",
          "title": "Reverse-engineer Shopify Admin, Storefront GraphQL, and Functions APIs",
          "status": "done",
          "verification": "Inspect documentation via shopify-dev MCP and live browser_subagent inspection."
        },
        {
          "id": "PHASE1-02",
          "title": "Produce Comprehensive Architectural Blueprint and Diagrams",
          "status": "done",
          "verification": "docs/ARCHITECTURE.md exists with system diagram and multi-tenancy spec."
        },
        {
          "id": "PHASE1-03",
          "title": "Draft Dual GraphQL and REST API Specification",
          "status": "done",
          "verification": "docs/API_SPEC.md exists with Storefront & Admin GraphQL schemas and Webhook catalog."
        },
        {
          "id": "PHASE1-04",
          "title": "Record Architectural Decisions (ADRs)",
          "status": "done",
          "verification": "docs/DECISIONS.md records ADR-001 through ADR-006."
        },
        {
          "id": "PHASE1-05",
          "title": "Establish Machine-Verifiable PRD for Ralph Loop",
          "status": "done",
          "verification": "prd.json valid and parseable."
        }
      ]
    },
    {
      "phase": 2,
      "title": "Design System, Branding & Visual Tokens",
      "status": "done",
      "stories": [
        {
          "id": "PHASE2-01",
          "title": "Synthesize VENDR Visual DNA & DESIGN.md",
          "status": "done",
          "verification": "DESIGN.md written with full color system, typography, density tokens, and component guidelines."
        },
        {
          "id": "PHASE2-02",
          "title": "Generate Brand Assets & Logos",
          "status": "done",
          "verification": "SVG logos and banners generated for open-source repository and README."
        },
        {
          "id": "PHASE2-03",
          "title": "Build Shared UI Token Library",
          "status": "done",
          "verification": "packages/ui contains Tailwind tokens and base Polaris-grade components."
        }
      ]
    },
    {
      "phase": 3,
      "title": "Core SaaS Backend & Multi-Tenant Engine",
      "status": "done",
      "stories": [
        {
          "id": "PHASE3-01",
          "title": "Scaffold Turborepo Monorepo with pnpm",
          "status": "done",
          "verification": "pnpm install succeeds and turborepo build pipeline executes cleanly."
        },
        {
          "id": "PHASE3-02",
          "title": "Implement PostgreSQL Multi-Tenant Schema with Prisma",
          "status": "done",
          "verification": "Prisma schema includes Store, Product, Variant, Inventory, Order, Customer, Metafield models."
        },
        {
          "id": "PHASE3-03",
          "title": "Build Fastify Backend with Storefront & Admin GraphQL Resolvers",
          "status": "done",
          "verification": "Fastify server handles GraphQL queries and mutations with multi-tenant context."
        },
        {
          "id": "PHASE3-04",
          "title": "Implement 1-Page & 3-Step Headless Checkout Engine",
          "status": "done",
          "verification": "Cart lifecycle (create, line additions, discount codes, checkout complete) tests pass."
        },
        {
          "id": "PHASE3-05",
          "title": "Implement Event-Driven Webhooks & BullMQ Dispatcher",
          "status": "done",
          "verification": "Webhook emission test confirms signed HMAC delivery."
        },
        {
          "id": "PHASE3-06",
          "title": "Implement Sandboxed WASM Functions Engine",
          "status": "done",
          "verification": "WASM runner executes discount and validation logic in <5ms."
        }
      ]
    },
    {
      "phase": 4,
      "title": "Next.js Merchant Admin, Visual Theme Builder & Storefront",
      "status": "done",
      "stories": [
        {
          "id": "PHASE4-01",
          "title": "Build Polaris-Grade Next.js Merchant Admin Dashboard",
          "status": "done",
          "verification": "apps/admin builds with zero errors; includes Orders, Products, Customers, Analytics."
        },
        {
          "id": "PHASE4-02",
          "title": "Build Visual Split-Screen Theme Customizer (Theme Editor)",
          "status": "done",
          "verification": "apps/theme-editor allows drag-and-drop sections, setting updates, and live preview."
        },
        {
          "id": "PHASE4-03",
          "title": "Build High-Performance Next.js Default Storefront Theme",
          "status": "done",
          "verification": "apps/storefront renders sub-100ms product pages, slide-out AJAX cart, and checkout."
        },
        {
          "id": "PHASE4-04",
          "title": "Run Performance & Accessibility Verification Gate",
          "status": "done",
          "verification": "All apps compile cleanly with zero TypeScript errors; Lighthouse audit ready."
        }
      ]
    },
    {
      "phase": 5,
      "title": "Unified Flutter Mobile & Desktop Omni-App",
      "status": "done",
      "stories": [
        {
          "id": "PHASE5-01",
          "title": "Scaffold Flutter Clean Architecture Omni-App",
          "status": "done",
          "verification": "apps/vendr-omni-app configured with Riverpod, Dio GraphQL client, and routing."
        },
        {
          "id": "PHASE5-02",
          "title": "Implement Live Store Pulse & Order Notification Screen",
          "status": "done",
          "verification": "Real-time GMV stats, active orders feed, and fulfillment actions implemented."
        },
        {
          "id": "PHASE5-03",
          "title": "Implement Barcode Scanner & POS Terminal",
          "status": "done",
          "verification": "Camera scanner interface and quick POS checkout module built."
        },
        {
          "id": "PHASE5-04",
          "title": "Implement AI Merchant Copilot Chat",
          "status": "done",
          "verification": "Natural language copilot interface connected to store APIs."
        }
      ]
    },
    {
      "phase": 6,
      "title": "DevOps, Docker, Kubernetes & Open-Source Release",
      "status": "done",
      "stories": [
        {
          "id": "PHASE6-01",
          "title": "Create Multi-Stage Production Dockerfiles and Docker Compose",
          "status": "done",
          "verification": "docker-compose.yml bootstraps backend, admin, storefront, postgres, and redis."
        },
        {
          "id": "PHASE6-02",
          "title": "Author Enterprise Kubernetes (k8s/) Manifests",
          "status": "done",
          "verification": "k8s/ includes Deployments, Services, Ingress, and HPA definitions."
        },
        {
          "id": "PHASE6-03",
          "title": "Author World-Class Open-Source Documentation",
          "status": "done",
          "verification": "README.md, CONTRIBUTING.md, LICENSE, and SECURITY.md created with high polish."
        },
        {
          "id": "PHASE6-04",
          "title": "Publish to GitHub and Verify CI/CD",
          "status": "done",
          "verification": "Repository prepared with GitHub Actions CI workflow for automated testing and builds."
        }
      ]
    },
    {
      "phase": 7,
      "title": "Live Adversarial Audit vs Real Shopify.com",
      "status": "done",
      "stories": [
        {
          "id": "PHASE7-01",
          "title": "Live Browser Subagent Inspection of shopify.com and shopify.dev",
          "status": "done",
          "verification": "browser_subagent navigates live shopify.com and shopify.dev; captures typography, layout rhythm, pricing tiers, and conversion elements."
        },
        {
          "id": "PHASE7-02",
          "title": "Author Comprehensive Gap & Parity Audit Document (docs/AUDIT_VS_SHOPIFY.md)",
          "status": "done",
          "verification": "docs/AUDIT_VS_SHOPIFY.md generated with visual, functional, pricing, and architectural comparisons."
        }
      ]
    },
    {
      "phase": 8,
      "title": "Enterprise Public Marketing Experience (apps/web-marketing)",
      "status": "done",
      "stories": [
        {
          "id": "PHASE8-01",
          "title": "Scaffold apps/web-marketing Next.js 15 App",
          "status": "done",
          "verification": "pnpm workspace configuration and Next.js 15 app router initialized."
        },
        {
          "id": "PHASE8-02",
          "title": "Implement Conversion Hero with Live Store Builder Preview & Theme Switcher",
          "status": "done",
          "verification": "Interactive hero section allowing instant theme switching and responsive preview."
        },
        {
          "id": "PHASE8-03",
          "title": "Implement Global Enterprise Metrics Ticker & POS Hardware Showcase",
          "status": "done",
          "verification": "Interactive tabs for Online Store, POS Terminal, B2B Wholesale, and International Commerce."
        },
        {
          "id": "PHASE8-04",
          "title": "Implement Pricing Comparison Matrix ($0 Open Source vs Shopify)",
          "status": "done",
          "verification": "Interactive ROI calculator contrasting VENDR zero transaction fees against Shopify 0.5-2.0% fees + subscriptions."
        },
        {
          "id": "PHASE8-05",
          "title": "Implement Developer Playground with Interactive GraphQL & WASM Previewer",
          "status": "done",
          "verification": "Live code viewer with copyable Storefront GraphQL queries and WASM function execution sample."
        },
        {
          "id": "PHASE8-06",
          "title": "Verify Production Build of apps/web-marketing",
          "status": "done",
          "verification": "pnpm --filter @vendr/web-marketing build completes with zero errors."
        }
      ]
    },
    {
      "phase": 9,
      "title": "Universal OS Matrix for Omni-App (Android, iOS, Windows, macOS, Linux)",
      "status": "done",
      "stories": [
        {
          "id": "PHASE9-01",
          "title": "Scaffold Complete OS Platform Runners in apps/vendr-omni-app",
          "status": "done",
          "verification": "android, ios, windows, macos, and linux runner configs verified in apps/vendr-omni-app."
        },
        {
          "id": "PHASE9-02",
          "title": "Author Multi-OS Release CI/CD Workflow (.github/workflows/release-all-platforms.yml)",
          "status": "done",
          "verification": "GitHub Actions matrix job configured to build APK, AAB, IPA, Windows MSIX/EXE, macOS DMG, and Linux AppImage/deb."
        }
      ]
    },
    {
      "phase": 10,
      "title": "Live Browser E2E, Auto-Heal Verification & Executive Publication",
      "status": "done",
      "stories": [
        {
          "id": "PHASE10-01",
          "title": "Spin Up Full Local Cluster & Execute Live Browser Subagent E2E User Journey",
          "status": "done",
          "verification": "Live browser subagent completes end-to-end journey: Storefront PDP -> Cart Drawer -> WASM Discount -> 1-Page Checkout Complete -> Admin Verification."
        },
        {
          "id": "PHASE10-02",
          "title": "Push Monorepo to GitHub and Author Executive Verification Report",
          "status": "done",
          "verification": "Monorepo clean build, git push, and EXECUTIVE_VERIFICATION_REPORT.md published."
        }
      ]
    }
  ]
}

{
  "$schema": "https://turbo.build/schema.json",
  "tasks": {
    "build": {
      "dependsOn": ["^build"],
      "outputs": [".next/**", "!.next/cache/**", "dist/**"]
    },
    "test": {
      "dependsOn": ["^build"],
      "outputs": ["coverage/**"]
    },
    "lint": {
      "dependsOn": ["^build"]
    },
    "dev": {
      "cache": false,
      "persistent": true
    }
  }
}
